```solidity
    modifier onlyProjectAdmin(address uniV3Pool) {
        require(_cachedProject[uniV3Pool].admin == msg.sender || _owner == msg.sender, "UA"); // allow the _owner of the ILOManager contract too
        _;
    }
```

