        result = prod0 * inv;
        return result;
    }

    /// @notice Calculates ceil(a×b÷denominator) with full precision. Throws if result overflows a uint256 or denominator == 0
    /// @param a The multiplicand
    /// @param b The multiplier
    /// @param denominator The divisor
    /// @return result The 256-bit result
    function mulDivRoundingUp(uint256 a, uint256 b, uint256 denominator) internal pure returns (uint256 result) {
        result = mulDiv(a, b, denominator);
        if (mulmod(a, b, denominator) > 0) {
            require(result < type(uint256).max);
            result++;
        }
    }
}
```

This library is taken from [Uniswap v3-core](https://github.com/Uniswap/v3-core/blob/main/contracts/libraries/FullMath.sol), which is designed for solidity version `>=0.4.0 <0.8.0`, where overflow does not cause the call to revert.

Note that the `UniswapV3Oracle` has solidity version > 0.8: 

[UniswapV3Oracle.sol#L2](https://github.com/code-423n4/2024-06-vultisig/blob/main/hardhat-vultisig/contracts/oracles/uniswap/UniswapV3Oracle.sol#L2)
```javascript
pragma solidity ^0.8.24;
```

This version will revert when overflow occurs, causing DoS.

